-- AI 助理前置种子数据
-- 生成时间: 2026-08-26 14:50:28
-- 说明: 10 名教练 + 10 个套餐模板 + 20 名用户，每名用户至少 1 条 active 套餐

SET FOREIGN_KEY_CHECKS = 0;
SET NAMES utf8mb4;

-- 清理已存在的种子数据，确保脚本可重复执行
DELETE FROM `package` WHERE package_no LIKE 'P-SEED-%';
DELETE FROM `order` WHERE order_no LIKE 'O-SEED-%';
DELETE FROM `user` WHERE openid LIKE 'seed_u_%';
DELETE FROM package_template_coach WHERE package_template_id IN (SELECT id FROM package_template WHERE name IN ('成人一对一私教10节', '儿童一对二小班8节', '零基础体验课2节', '仰泳专项提升6节', '蝶泳进阶私教8节', '亲子一对三欢乐课12节', '中考游泳冲刺10节', '成人自由泳速成5节', '儿童蛙泳启蒙6节', '全泳姿全能班20节'));
DELETE FROM package_template WHERE name IN ('成人一对一私教10节', '儿童一对二小班8节', '零基础体验课2节', '仰泳专项提升6节', '蝶泳进阶私教8节', '亲子一对三欢乐课12节', '中考游泳冲刺10节', '成人自由泳速成5节', '儿童蛙泳启蒙6节', '全泳姿全能班20节');
DELETE FROM coach WHERE openid LIKE 'seed_c_%';

SET @coach_base = (SELECT COALESCE(MAX(id),0)+10000 FROM coach);
SET @tmpl_base  = (SELECT COALESCE(MAX(id),0)+10000 FROM package_template);
SET @user_base  = (SELECT COALESCE(MAX(id),0)+10000 FROM `user`);
SET @order_base = (SELECT COALESCE(MAX(id),0)+10000 FROM `order`);
SET @pkg_base   = (SELECT COALESCE(MAX(id),0)+10000 FROM `package`);

